         let lock =
             atomic_with_ghost!(
             self.lock => fetch_add(READER);
             update prev -> next;
             ghost g => {
                 let prev_usize = prev as usize;
                 lemma_consts_properties_value(prev_usize);
                 assert(no_max_reader_overflow(prev_usize)) by (nonlinear_arith);
                 if prev_usize & (WRITER | MAX_READER | BEING_UPGRADED) == 0 {
                     assert(g.core_token.is_left());
                     let tracked mut read_guards = g.read_guard_token.tracked_take_left();
                     read_guards.validate();
                     let tracked token = read_guards.split_one();
                     g.read_guard_token = Sum::tracked_new_left(read_guards);
                     read_token = Some(token);
                 } else {
                     let tracked token = g.read_retract_token.split_one();
                     retract_read_token = Some(token);
                 }
             }
         );
         if lock & (WRITER | MAX_READER | BEING_UPGRADED) == 0 {
             Some(
                 RwLockReadGuard {
                     inner: self,
                     guard,
                     tracked_token: Tracked(read_token.tracked_unwrap()),
                 },
             )
         } else {
             atomic_with_ghost!(
                 self.lock => fetch_sub(READER);
                 update prev -> next;
                 ghost g => {
                     let tracked token = retract_read_token.tracked_unwrap();
                     g.read_retract_token.combine(token);
                 }
             );
             None
         }
     }

